macro_rules! deps {
    () => {
        Exfiltrator!();
    };
}

macro_rules! sealed {
    () => {
        deps!();
        mod sealed { use std :: fmt :: Debug ; use libc :: { c_int , siginfo_t } ; # [doc = " The actual implementation of the [`Exfiltrator`][super::Exfiltrator]."] # [doc = ""] # [doc = " For now, this is hidden from the public API, but the intention is to move it to a public"] # [doc = " place so users can implement it eventually, once we verify that it works well."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The trait is unsafe as the [`Exfiltrator::store`] is called inside the signal handler and"] # [doc = " must be async-signal-safe. Implementing this correctly may be difficult, therefore care"] # [doc = " needs to be taken. One method known to work is encoding the data into an atomic variable."] # [doc = " Other, less limiting approaches, will be eventually explored."] pub unsafe trait Exfiltrator : Debug + Send + Sync + 'static { # [doc = " One slot for storing the data."] # [doc = ""] # [doc = " Each signal will get its one slot of this type, independent of other signals. It can"] # [doc = " store the information in there inside the signal handler and will be loaded from it in"] # [doc = " load."] # [doc = ""] # [doc = " Each slot is initialized to the [`Default`] value. It is expected this value represents"] # [doc = " „no signal delivered“ state."] type Storage : Debug + Default + Send + Sync + 'static ; # [doc = " The type returned to the user."] type Output ; # [doc = " If the given signal is supported by this specific exfiltrator."] # [doc = ""] # [doc = " Not all information is available to all signals, therefore not all exfiltrators must"] # [doc = " support all signals. If `false` is returned, the user is prevented for registering such"] # [doc = " signal number with the given exfiltrator."] fn supports_signal (& self , sig : c_int) -> bool ; # [doc = " Puts the signal information inside the slot."] # [doc = ""] # [doc = " It needs to somehow store the relevant information and the fact that a signal happened."] # [doc = ""] # [doc = " # Warning"] # [doc = ""] # [doc = " This will be called inside the signal handler. It needs to be async-signal-safe. In"] # [doc = " particular, very small amount of operations are allowed in there. This namely does"] # [doc = " *not* include any locking nor allocation."] # [doc = ""] # [doc = " It is also possible that multiple store methods are called concurrently; it is up to"] # [doc = " the implementor to deal with that."] fn store (& self , slot : & Self :: Storage , signal : c_int , info : & siginfo_t) ; # [doc = " Loads the signal information from the given slot."] # [doc = ""] # [doc = " The method shall check if the signal happened (it may be possible to be called without"] # [doc = " the signal previously being delivered; it is up to the implementer to recognize it). It"] # [doc = " is assumed the [`Default`] value is recognized as no signal delivered."] # [doc = ""] # [doc = " If it was delivered, the method shall extract the relevant information *and reset the"] # [doc = " slot* to the no signal delivered state."] # [doc = ""] # [doc = " It shall return `Some(value)` if the signal was successfully received and `None` in"] # [doc = " case no signal was delivered."] # [doc = ""] # [doc = " No blocking shall happen inside this method. It may be called concurrently with"] # [doc = " [`store`][Exfiltrator::store] (due to how signals work, concurrently even inside the"] # [doc = " same thread ‒ a `store` may „interrupt“ a call to `load`). It is up to the implementer"] # [doc = " to deal with that."] fn load (& self , slot : & Self :: Storage , signal : c_int) -> Option < Self :: Output > ; # [doc = " Initialize the given slot for the given signal before the first use."] # [doc = ""] # [doc = " This is called before the first use of the given slot (and it is annotated with the"] # [doc = " corresponding signal). The default does nothing, this is just an opportunity to"] # [doc = " allocate data lazily (this is called outside of the signal handler, so it doesn't have"] # [doc = " to be async-signal-safe). It will be called at most once for each slot."] # [doc = ""] # [doc = " Note that you can rely on this being called for correctness, but not for safety (this"] # [doc = " crate calls it before the first use, but a user abusing the trait might not and in such"] # [doc = " case it is OK to eg. lose signals, but not segfault)."] fn init (& self , slot : & Self :: Storage , signal : c_int) { let _ = slot ; let _ = signal ; } } }
    };
}

sealed!();